import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Image,
  PanResponder,
  Pressable,
  StyleSheet,
  Text,
  View,
  type LayoutChangeEvent,
  type PanResponderInstance,
} from 'react-native';

import {
  applyPanDelta,
  applyPinchRotate,
  createInitialMapTransform,
  mapTransformsEqual,
  type MapTransform,
  type ViewportDimensions,
  type ViewportPoint,
} from './mapTransform';

interface MapViewportProps {
  imageUri: string;
  onTransformChange?: (transform: MapTransform) => void;
}

interface GestureTracking {
  mode: 'none' | 'pan' | 'pinch';
  lastPanPoint: ViewportPoint | null;
  pinchStartDistance: number;
  pinchStartAngle: number;
  pinchStartTransform: MapTransform;
}

function touchPoint(touch: { locationX: number; locationY: number }): ViewportPoint {
  return {
    x: touch.locationX,
    y: touch.locationY,
  };
}

function distance(a: ViewportPoint, b: ViewportPoint): number {
  return Math.hypot(b.x - a.x, b.y - a.y);
}

function angle(a: ViewportPoint, b: ViewportPoint): number {
  return Math.atan2(b.y - a.y, b.x - a.x);
}

function midpoint(a: ViewportPoint, b: ViewportPoint): ViewportPoint {
  return {
    x: (a.x + b.x) / 2,
    y: (a.y + b.y) / 2,
  };
}

function formatTransformValue(value: number): string {
  if (!Number.isFinite(value)) {
    return '0';
  }

  return value.toFixed(2);
}

export function MapViewport({ imageUri, onTransformChange }: MapViewportProps) {
  const [viewport, setViewport] = useState<ViewportDimensions | null>(null);
  const [transform, setTransform] = useState<MapTransform>(createInitialMapTransform);

  const gesture = useRef<GestureTracking>({
    mode: 'none',
    lastPanPoint: null,
    pinchStartDistance: 0,
    pinchStartAngle: 0,
    pinchStartTransform: createInitialMapTransform(),
  });

  useEffect(() => {
    onTransformChange?.(transform);
  }, [onTransformChange, transform]);

  const commitTransform = useCallback((updater: (current: MapTransform) => MapTransform) => {
    setTransform((current) => {
      const next = updater(current);
      return mapTransformsEqual(current, next) ? current : next;
    });
  }, []);

  const panResponder: PanResponderInstance = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => true,
        onMoveShouldSetPanResponder: () => true,
        onPanResponderGrant: (event) => {
          const touches = event.nativeEvent.touches;

          if (touches.length >= 2) {
            const first = touches[0];
            const second = touches[1];
            if (!first || !second) {
              return;
            }

            const a = touchPoint(first);
            const b = touchPoint(second);
            gesture.current.mode = 'pinch';
            gesture.current.pinchStartDistance = distance(a, b);
            gesture.current.pinchStartAngle = angle(a, b);
            gesture.current.pinchStartTransform = transform;
            gesture.current.lastPanPoint = null;
            return;
          }

          const first = touches[0];
          if (!first) {
            return;
          }

          gesture.current.mode = 'pan';
          gesture.current.lastPanPoint = touchPoint(first);
        },
        onPanResponderMove: (event) => {
          const touches = event.nativeEvent.touches;

          if (touches.length >= 2) {
            const first = touches[0];
            const second = touches[1];
            if (!first || !second) {
              return;
            }

            const firstPoint = touchPoint(first);
            const secondPoint = touchPoint(second);

            if (gesture.current.mode !== 'pinch' || gesture.current.pinchStartDistance <= 0) {
              gesture.current.mode = 'pinch';
              gesture.current.pinchStartDistance = distance(firstPoint, secondPoint);
              gesture.current.pinchStartAngle = angle(firstPoint, secondPoint);
              gesture.current.pinchStartTransform = transform;
              gesture.current.lastPanPoint = null;
              return;
            }

            const currentDistance = distance(firstPoint, secondPoint);
            const currentAngle = angle(firstPoint, secondPoint);
            if (!Number.isFinite(currentDistance) || currentDistance <= 0 || !Number.isFinite(currentAngle)) {
              return;
            }

            const scaleFactor = currentDistance / gesture.current.pinchStartDistance;
            const rotationDeltaDeg = ((currentAngle - gesture.current.pinchStartAngle) * 180) / Math.PI;
            const focal = midpoint(firstPoint, secondPoint);

            commitTransform(() =>
              applyPinchRotate(gesture.current.pinchStartTransform, {
                scaleFactor,
                rotationDeltaDeg,
                focal,
                viewport,
              }),
            );

            return;
          }

          if (touches.length === 1) {
            const touch = touches[0];
            if (!touch) {
              return;
            }

            const point = touchPoint(touch);

            if (gesture.current.mode !== 'pan' || !gesture.current.lastPanPoint) {
              gesture.current.mode = 'pan';
              gesture.current.lastPanPoint = point;
              return;
            }

            const delta = {
              x: point.x - gesture.current.lastPanPoint.x,
              y: point.y - gesture.current.lastPanPoint.y,
            };

            commitTransform((current) => applyPanDelta(current, delta));
            gesture.current.lastPanPoint = point;
            return;
          }

          gesture.current.mode = 'none';
          gesture.current.lastPanPoint = null;
        },
        onPanResponderRelease: () => {
          gesture.current.mode = 'none';
          gesture.current.lastPanPoint = null;
          gesture.current.pinchStartDistance = 0;
        },
        onPanResponderTerminate: () => {
          gesture.current.mode = 'none';
          gesture.current.lastPanPoint = null;
          gesture.current.pinchStartDistance = 0;
        },
      }),
    [commitTransform, transform, viewport],
  );

  const onLayout = (event: LayoutChangeEvent) => {
    const { width, height } = event.nativeEvent.layout;
    if (width <= 0 || height <= 0) {
      return;
    }

    setViewport({ width, height });
  };

  const applyScaleAtViewportCenter = (scaleFactor: number) => {
    commitTransform((current) =>
      applyPinchRotate(current, {
        scaleFactor,
        rotationDeltaDeg: 0,
        focal: {
          x: viewport ? viewport.width / 2 : 0,
          y: viewport ? viewport.height / 2 : 0,
        },
        viewport,
      }),
    );
  };

  const applyRotationAtViewportCenter = (rotationDeltaDeg: number) => {
    commitTransform((current) =>
      applyPinchRotate(current, {
        scaleFactor: 1,
        rotationDeltaDeg,
        focal: {
          x: viewport ? viewport.width / 2 : 0,
          y: viewport ? viewport.height / 2 : 0,
        },
        viewport,
      }),
    );
  };

  return (
    <View style={styles.container}>
      <View style={styles.controls}>
        <Pressable onPress={() => applyScaleAtViewportCenter(1.2)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Zoom +</Text>
        </Pressable>
        <Pressable onPress={() => applyScaleAtViewportCenter(1 / 1.2)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Zoom -</Text>
        </Pressable>
        <Pressable onPress={() => applyRotationAtViewportCenter(-15)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Rotate ↺</Text>
        </Pressable>
        <Pressable onPress={() => applyRotationAtViewportCenter(15)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Rotate ↻</Text>
        </Pressable>
        <Pressable onPress={() => setTransform(createInitialMapTransform())} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Reset</Text>
        </Pressable>
      </View>

      <View style={styles.viewport} onLayout={onLayout} {...panResponder.panHandlers}>
        <Image
          source={{ uri: imageUri }}
          resizeMode="contain"
          style={[
            styles.mapImage,
            {
              transform: [
                { translateX: transform.translation.x },
                { translateY: transform.translation.y },
                { rotateZ: `${transform.rotationDeg}deg` },
                { scale: transform.scale },
              ],
            },
          ]}
        />
      </View>

      <Text style={styles.telemetry}>
        scale={formatTransformValue(transform.scale)} rotation={formatTransformValue(transform.rotationDeg)}° tx=
        {formatTransformValue(transform.translation.x)} ty={formatTransformValue(transform.translation.y)}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    width: '100%',
    flex: 1,
    gap: 8,
  },
  controls: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 6,
  },
  controlButton: {
    backgroundColor: '#0f172a',
    borderColor: '#334155',
    borderWidth: 1,
    borderRadius: 8,
    paddingHorizontal: 10,
    paddingVertical: 6,
  },
  controlButtonText: {
    color: '#e2e8f0',
    fontSize: 12,
    fontWeight: '600',
  },
  viewport: {
    flex: 1,
    minHeight: 280,
    borderRadius: 12,
    borderWidth: 1,
    borderColor: '#334155',
    overflow: 'hidden',
    backgroundColor: '#020617',
  },
  mapImage: {
    width: '100%',
    height: '100%',
  },
  telemetry: {
    color: '#94a3b8',
    fontSize: 12,
    fontVariant: ['tabular-nums'],
  },
});

/**
 * MapViewportFloor — floor-switching extension of MapViewport.
 *
 * Composes:
 * - MapViewport (floor plan image with pan/pinch/rotate controls)
 * - Floor selector strip (horizontal ScrollView of floor buttons)
 * - RoutePathOverlay (polyline overlay on active floor)
 *
 * The active floor target is tracked in state and drives both
 * which image is shown and which floor segment is rendered.
 */

import { useCallback, useEffect, useState } from 'react';
import {
  FlatList,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';

import { MapViewport } from './MapViewport';
import { RoutePathOverlay, type RoutePathPoint } from '../components/route/RoutePathOverlay';
import type { FloorPlanTarget } from '../data/mapApiClient';
import type { MapTransform } from './mapTransform';
import type { ViewportDimensions } from './mapTransform';

/* ─── Props ─── */

export interface MapViewportFloorProps {
  /** MapViewport props */
  onTransformChange?: (transform: MapTransform) => void;
  /** All available floor targets for the active route */
  floorTargets: FloorPlanTarget[];
  /** Currently selected floor target */
  activeFloorTarget: FloorPlanTarget | null;
  /** Floor ID for the active target (used for route path overlay filtering) */
  activeFloorId: number;
  /** Route path waypoints (normalized coordinates) */
  routePath: RoutePathPoint[];
  /** Called when user presses a floor button */
  onFloorChange: (target: FloorPlanTarget) => void;
  /** Whether to show the route path overlay */
  showRouteOverlay?: boolean;
  /** Whether to show the floor selector strip */
  showFloorSelector?: boolean;
}

/* ─── State ─── */

interface FloorButtonData {
  target: FloorPlanTarget;
  label: string;
  isActive: boolean;
}

/* ─── Component ─── */

export function MapViewportFloor({
  onTransformChange,
  floorTargets,
  activeFloorTarget,
  activeFloorId,
  routePath,
  onFloorChange,
  showRouteOverlay = true,
  showFloorSelector = true,
}: MapViewportFloorProps) {
  const [transform, setTransform] = useState<MapTransform>({
    scale: 1,
    rotationDeg: 0,
    translation: { x: 0, y: 0 },
  });
  const [viewportDimensions, setViewportDimensions] = useState<ViewportDimensions>({ width: 300, height: 300 });

  const handleTransformChange = useCallback(
    (t: MapTransform) => {
      setTransform(t);
      onTransformChange?.(t);
    },
    [onTransformChange],
  );

  // Build floor button data
  const floorButtons: FloorButtonData[] = floorTargets.map(target => ({
    target,
    label: `Bldg ${target.buildingId} Fl ${target.floorNumber}`,
    isActive: activeFloorTarget !== null
      && activeFloorTarget.buildingId === target.buildingId
      && activeFloorTarget.floorNumber === target.floorNumber,
  }));

  return (
    <View style={styles.container}>
      {/* Map viewport with optional route overlay */}
      <View style={styles.mapContainer}>
        <MapViewport
          imageUri=""
          onTransformChange={handleTransformChange}
        />
        {showRouteOverlay && activeFloorTarget && (
          <RoutePathOverlay
            path={routePath}
            activeFloorId={activeFloorId}
            viewport={viewportDimensions}
            scale={transform.scale}
          />
        )}
      </View>

      {/* Floor selector strip */}
      {showFloorSelector && floorButtons.length > 0 && (
        <View style={styles.floorSelector}>
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={styles.floorScrollContent}
          >
            {floorButtons.map((btn, idx) => (
              <Pressable
                key={`floor-${idx}`}
                style={[styles.floorButton, btn.isActive && styles.floorButtonActive]}
                onPress={() => onFloorChange(btn.target)}
              >
                <Text style={[styles.floorButtonText, btn.isActive && styles.floorButtonTextActive]}>
                  {btn.label}
                </Text>
              </Pressable>
            ))}
          </ScrollView>
        </View>
      )}
    </View>
  );
}

/* ─── Styles ─── */

const styles = StyleSheet.create({
  container: {
    width: '100%',
    gap: 8,
  },
  mapContainer: {
    flex: 1,
    minHeight: 280,
    borderRadius: 12,
    overflow: 'hidden',
  },
  floorSelector: {
    paddingVertical: 4,
  },
  floorScrollContent: {
    flexDirection: 'row',
    gap: 8,
    paddingHorizontal: 4,
    paddingVertical: 4,
  },
  floorButton: {
    backgroundColor: '#0f172a',
    borderColor: '#334155',
    borderWidth: 1,
    borderRadius: 8,
    paddingHorizontal: 12,
    paddingVertical: 6,
  },
  floorButtonActive: {
    backgroundColor: '#0c2d4a',
    borderColor: '#38bdf8',
    borderWidth: 1.5,
  },
  floorButtonText: {
    color: '#94a3b8',
    fontSize: 12,
    fontWeight: '500',
  },
  floorButtonTextActive: {
