          >
            <Text style={[styles.toggleButtonText, accessibleMode && styles.toggleButtonTextActive]}>
              {accessibleMode ? 'ON' : 'OFF'}
            </Text>
          </Pressable>
        </View>

        {/* Telemetry */}
